CREATE TABLE events (
 id UUID PRIMARY KEY, slug VARCHAR(160) NOT NULL UNIQUE, category VARCHAR(40) NOT NULL,
 start_at TIMESTAMP WITH TIME ZONE NOT NULL, end_at TIMESTAMP WITH TIME ZONE, timezone VARCHAR(80) NOT NULL,
 location TEXT, virtual_url TEXT, image_url TEXT, display_order INTEGER NOT NULL DEFAULT 0,
 status VARCHAR(30) NOT NULL DEFAULT 'DRAFT', featured BOOLEAN NOT NULL DEFAULT FALSE,
 highlighted BOOLEAN NOT NULL DEFAULT FALSE, capacity INTEGER, translations JSONB NOT NULL DEFAULT '{}'::jsonb,
 created_at TIMESTAMP WITH TIME ZONE NOT NULL, updated_at TIMESTAMP WITH TIME ZONE NOT NULL,
 CONSTRAINT chk_event_status CHECK (status IN ('DRAFT','PUBLISHED','CANCELLED','ARCHIVED')),
 CONSTRAINT chk_event_category CHECK (category IN ('in-person','virtual','hybrid'))
);
CREATE INDEX idx_events_public ON events(status, start_at, display_order);

